def resolve(path, cwd, links):
    # Validate cwd is canonical and absolute
    if not cwd.startswith('/') or cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative, otherwise use '/'
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent directory
                if current != '/':
                    # Remove last component
                    last_slash = current.rfind('/')
                    if last_slash == 0:
                        current = '/'
                    else:
                        current = current[:last_slash]
                continue

            # Append the component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current is a symlink
            if current in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[current]

                # Determine the remaining path after this component
                # Get index of current component in the original components list
                component_index = components.index(component)
                remaining_components = components[component_index + 1:]
                remaining_path = '/'.join(remaining_components)

                # Resolve the target
                if target.startswith('/'):
                    # Absolute target
                    current = '/'
                    remaining = target[1:]
                else:
                    # Relative target - relative to directory containing the link
                    link_dir = current[:current.rfind('/')]
                    if link_dir == '':
                        link_dir = '/'
                    current = link_dir
                    remaining = target

                # Append remaining path
                if remaining_path:
                    if remaining == '':
                        remaining = remaining_path
                    else:
                        remaining = remaining + '/' + remaining_path

                # Break to restart component processing with new remaining path
                break
        else:
            # All components processed without finding a symlink
            # Remove trailing slash except for '/'
            if current != '/' and current.endswith('/'):
                current = current[:-1]
            return current

